INSERT INTO `pages` VALUES (1,'About Us','about-us','<p>ShopBD is a Bangladeshi online store on a mission to make genuine products affordable and accessible to everyone, everywhere in the country.</p><h2>Why shop with us?</h2><ul><li>100% authentic products sourced directly from brands and authorised distributors</li><li>Cash on Delivery across all 64 districts</li><li>Fast delivery – 24 hours inside Dhaka</li><li>Easy 7-day return &amp; exchange</li><li>Friendly support team, 7 days a week</li></ul>',1,NULL,NULL,'2026-11-11 13:23:26','2026-11-11 13:23:26');
INSERT INTO `pages` VALUES (2,'Privacy Policy','privacy-policy','<p>We respect your privacy. We only collect the information needed to process your orders (name, phone, address and optionally email) and never sell your personal data.</p><h2>Information we collect</h2><p>Order details, contact information and basic analytics to improve our service.</p><h2>How we use it</h2><p>To deliver your orders, provide support and – only if you subscribe – send offers.</p><h2>Contact</h2><p>Questions? Contact us any time from the Contact page.</p>',1,NULL,NULL,'2026-11-11 13:23:26','2026-11-11 13:23:26');
INSERT INTO `pages` VALUES (3,'Terms and Conditions','terms-and-conditions','<p>By using this website you agree to the following terms.</p><h2>Orders</h2><p>All orders are subject to availability and confirmation by phone. Prices may change without prior notice.</p><h2>Payment</h2><p>We accept Cash on Delivery, bKash and Nagad.</p><h2>Delivery</h2><p>Delivery times are estimates and may vary during holidays or bad weather.</p>',1,NULL,NULL,'2026-11-11 13:23:26','2026-11-11 13:23:26');
INSERT INTO `pages` VALUES (4,'Return Policy','return-policy','<p>Not happy? You can return or exchange most items within <strong>7 days</strong> of delivery.</p><ul><li>The product must be unused and in its original packaging</li><li>Damaged or wrong items are replaced free of charge</li><li>Refunds are processed within 3–5 working days via bKash or bank</li></ul>',1,NULL,NULL,'2026-11-11 13:23:26','2026-11-11 13:23:26');
INSERT INTO `pages` VALUES (5,'Shipping Policy','shipping-policy','<table><tr><th>Area</th><th>Charge</th><th>Time</th></tr><tr><td>Inside Dhaka</td><td>৳70</td><td>1–2 days</td></tr><tr><td>Dhaka Suburbs</td><td>৳100</td><td>2–3 days</td></tr><tr><td>Outside Dhaka</td><td>৳130</td><td>2–4 days</td></tr></table><p>Free delivery on orders over ৳2,000.</p>',1,NULL,NULL,'2026-11-11 13:23:26','2026-11-11 13:23:26');
INSERT INTO `posts` VALUES (1,1,'How to Spot a Genuine Smartphone in Bangladesh','how-to-spot-a-genuine-smartphone-in-bangladesh','Buying a phone online? Here is a quick checklist to make sure you get an original device with official warranty.','<p>Buying a phone online? Here is a quick checklist to make sure you get an original device with official warranty.</p><h2>1. Start with the basics</h2><p>Always buy from a trusted shop that offers cash on delivery and a clear return policy. Check reviews from verified buyers before you order.</p><h2>2. Compare prices – but carefully</h2><p>If a price looks too good to be true, it probably is. Compare with official brand prices and look for warranty information.</p><h2>3. Check the product on delivery</h2><p>With Cash on Delivery you can inspect the package before paying. Keep the invoice for warranty claims.</p><blockquote>Tip: Subscribe to our newsletter to get early access to flash sales.</blockquote>','blog/post-0.jpg',1,'2026-11-08 13:23:57',NULL,NULL,'2026-11-11 13:23:57','2026-11-11 13:23:57');
INSERT INTO `posts` VALUES (2,1,'10 Kitchen Gadgets That Save You Time Every Day','10-kitchen-gadgets-that-save-you-time-every-day','From smart choppers to non-stick pans – the affordable tools that make cooking faster and more fun.','<p>From smart choppers to non-stick pans – the affordable tools that make cooking faster and more fun.</p><h2>1. Start with the basics</h2><p>Always buy from a trusted shop that offers cash on delivery and a clear return policy. Check reviews from verified buyers before you order.</p><h2>2. Compare prices – but carefully</h2><p>If a price looks too good to be true, it probably is. Compare with official brand prices and look for warranty information.</p><h2>3. Check the product on delivery</h2><p>With Cash on Delivery you can inspect the package before paying. Keep the invoice for warranty claims.</p><blockquote>Tip: Subscribe to our newsletter to get early access to flash sales.</blockquote>','blog/post-1.jpg',1,'2026-11-02 13:23:57',NULL,NULL,'2026-11-11 13:23:57','2026-11-11 13:23:57');
